index.scripts_propios:
/* Tres niveles, según lo que aguante la conexión del visitante:
     escritorio          -> el video completo
     móvil y tablet      -> una versión ligera, sin audio
     2G / ahorro datos / -> solo el poster (61 KB), que es el primer
     menos movimiento       fotograma del propio video                */
(function () {
  var v = document.getElementById('hero-video');
  if (!v) return;

  var con = navigator.connection || {};
  var lenta = con.saveData === true || /^(slow-)?2g$/.test(con.effectiveType || '');
  var menosMovimiento = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (lenta || menosMovimiento) return;   // se queda el poster

  var ligero = window.innerWidth < 860;
  v.src = v.getAttribute(ligero ? 'data-src-movil' : 'data-src');
  v.autoplay = true;
  var intento = v.play();
  if (intento && intento.catch) intento.catch(function () {});
})();

tripulacion.estilo_propio:
/* Custom styles for Tripulacion page */
    .crew-hero {
      background: linear-gradient(180deg, #0b2440, #0b2137);
      padding: 160px 40px 80px;
      text-align: center;
    }
    .crew-list {
      max-width: 1000px;
      margin: 0 auto;
      padding: 40px 40px 100px;
      display: flex;
      flex-direction: column;
      gap: 60px;
    }
    .crew-member {
      background: rgba(255,255,255,0.03);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: var(--radius-lg);
      overflow: hidden;
      display: grid;
      grid-template-columns: 1fr;
    }
    @media (min-width: 800px) {
      .crew-member { grid-template-columns: 1fr 1fr; }
      .crew-member:nth-child(even) .crew-video { order: 2; }
      .crew-member:nth-child(even) .crew-info { order: 1; }
    }
    .crew-video {
      position: relative;
      aspect-ratio: 16/9;
      background: #000;
    }
    @media (min-width: 800px) {
      .crew-video { aspect-ratio: auto; height: 100%; }
    }
    .crew-video video {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .crew-info {
      padding: 40px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }
    .crew-info .role {
      font-size: 0.85rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 12px;
      color: var(--turq-soft);
    }
    .crew-member:nth-child(2) .role { color: var(--mango); }
    .crew-member:nth-child(3) .role { color: var(--gold); }

    .crew-info h2 {
      font-size: clamp(1.6rem, 3vw, 2.4rem);
      margin-bottom: 20px;
      color: var(--paper);
    }
    .crew-info p {
      font-size: 1.05rem;
      line-height: 1.6;
      color: var(--ice);
      opacity: 0.85;
      margin-bottom: 24px;
    }
